import React from 'react';
import { Check, ArrowRight } from 'lucide-react';
import { motion } from 'framer-motion';
import '../styles/lists.css';

export default function SettlementList({ settlements, onSettle }) {
  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: { staggerChildren: 0.05 }
    }
  };

  const item = {
    hidden: { opacity: 0, x: -20 },
    show: { opacity: 1, x: 0 }
  };

  return (
    <motion.div
      className="list-container"
      variants={container}
      initial="hidden"
      animate="show"
    >
      {settlements.map((settlement) => (
        <motion.div
          key={settlement._id}
          className={`list-item settlement-item ${settlement.settled ? 'settled' : ''}`}
          variants={item}
        >
          <div className="item-content">
            <div className="item-icon">💰</div>
            <div className="item-info">
              <p className="item-title">
                {settlement.from?.name} <ArrowRight size={16} /> {settlement.to?.name}
              </p>
              <p className="item-subtitle">{settlement.settled ? '✓ Settled' : 'Pending'}</p>
            </div>
          </div>
          <div className="item-amount">${settlement.amount.toFixed(2)}</div>
          {!settlement.settled && (
            <button
              className="settle-btn"
              onClick={() => onSettle(settlement)}
            >
              <Check size={18} />
            </button>
          )}
        </motion.div>
      ))}
    </motion.div>
  );
}
